
local phsgo=[==[]==]
local ijyf=
(function(...)
local hep={147,93,141,213,107,21,72,153,12,251,19,96,159,30,15,98}
local riaot=bit32 or bit
local ofe=riaot.bxor
for vf=1,#hep do hep[vf]=ofe(hep[vf],(140*vf+85)%256) end
local cb="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local gmant={}
for jhy=1,#cb do gmant[cb:byte(jhy)]=jhy-1 end
local function mlcqp(str)
  local R={} local acc,nb=0,0
  for mth=1,#str do
    local v=gmant[str:byte(mth)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function ifcbf(key,data)
  local S={} for giju=0,255 do S[giju]=giju end
  local j=0
  for fsas=0,255 do
    j=(j+S[fsas]+key[(fsas%#key)+1])%256
    S[fsas],S[j]=S[j],S[fsas]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(ofe(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=ifcbf(hep,mlcqp(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local qim=nf()
return function(big) return qim(big) end
end)(...)

return ijyf(phsgo)
